-- Date pentru baza de PRODUCTIE — generat din baza locala verificata.
-- Contine structura si continutul celor 4 tabele de catalog.
-- NU atinge tabelele users, pages, audit_log, login_attempts.
--
-- Importa prin phpMyAdmin sau: mysql -u <user> -p <baza> < productie_date.sql
-- Presupune ca exista deja un user admin cu id=1 in tabela users.

SET FOREIGN_KEY_CHECKS=0;




DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_id` smallint unsigned DEFAULT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_parent` (`parent_id`),
  CONSTRAINT `fk_cat_parent` FOREIGN KEY (`parent_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


LOCK TABLES `categories` WRITE;
INSERT INTO `categories` (`id`, `slug`, `parent_id`, `name`, `sort_order`, `is_active`) VALUES (1,'acoperis',14,'Acoperis',1,1),(2,'izolatie',14,'Izolatie',2,1),(3,'gips-carton',14,'Gips Carton',3,1),(4,'zidarie-bca',14,'Zidarie BCA',4,1),(5,'gard-imprejmuiri',14,'Gard & Imprejmuiri',5,1),(6,'electrice',NULL,'Electrice',6,1),(7,'incalzire',NULL,'Incalzire',7,1),(8,'sanitare',NULL,'Sanitare',8,1),(9,'gradina',NULL,'Gradina',9,1),(10,'mobilier',NULL,'Mobilier',10,1),(11,'electrocasnice',NULL,'Electrocasnice',11,1),(12,'scule-unelte',NULL,'Scule & Unelte',12,1),(13,'apa-canal',NULL,'Apa & Canal',13,1),(14,'constructii',NULL,'Constructii',0,1),(15,'cabluri',6,'Cabluri & Conductori',1,1),(16,'becuri',6,'Becuri LED',2,1),(17,'aparataj',6,'Aparataj Electric',3,1),(18,'iluminat',6,'Corpuri Iluminat',4,1),(19,'centrale',7,'Centrale termice',1,1),(20,'radiatoare',7,'Radiatoare',2,1),(21,'aer-conditionat',7,'Aer conditionat',3,1),(22,'sobe',7,'Sobe & Seminee',4,1),(23,'baterii',8,'Baterii de apa',1,1),(24,'mobilier-baie',8,'Mobilier baie',2,1),(25,'accesorii-baie',8,'Accesorii baie',3,1),(26,'tevi',13,'Tevi & Fitting',1,1),(27,'canalizare',13,'Canalizare PVC',2,1),(28,'pompe',13,'Pompe de apa',3,1),(29,'living',10,'Living',1,1),(30,'dormitor',10,'Dormitor',2,1),(31,'bucatarie',10,'Bucatarie',3,1);
UNLOCK TABLES;


DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_id` smallint unsigned NOT NULL,
  `page_slug` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `card_kind` enum('material','accessory') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'material',
  `card_modifier` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `section_key` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `short_description` text COLLATE utf8mb4_unicode_ci,
  `wa_text` varchar(400) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_alt` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_key` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_label` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `badge_label` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `badge_kind` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(10,2) unsigned DEFAULT NULL,
  `price_unit` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_visible` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_by` int unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_page_section_name` (`page_slug`,`section_key`,`name`),
  KEY `idx_cat_sort` (`category_id`,`sort_order`,`is_visible`),
  KEY `created_by` (`created_by`),
  KEY `idx_page_section` (`page_slug`,`section_key`,`sort_order`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10485 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


LOCK TABLES `products` WRITE;
INSERT INTO `products` (`id`, `category_id`, `page_slug`, `card_kind`, `card_modifier`, `section_key`, `name`, `short_description`, `wa_text`, `image_path`, `image_alt`, `icon_key`, `icon_label`, `badge_label`, `badge_kind`, `price`, `price_unit`, `is_visible`, `sort_order`, `created_by`, `created_at`, `updated_at`) VALUES (1,1,'acoperis','material',NULL,'tipuri-de-invelitori','Tabla Cutata (Ondulata)','Profile ondulate sau trapezoidale, disponibila in zeci de culori RAL, suprafata mata sau lucioasa. Ofera un look industrial sau rustic, in functie de culoarea aleasa.','Buna ziua! Sunt interesat de tabla cutata pentru acoperis. Puteti sa imi dati un pret?','img/tabla-cutata.jpg','Tabla cutata acoperis','icon-191d7a27','Tabla cutata','Cel mai vandut','popular',NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-09-25 14:52:39'),(2,1,'acoperis','material',NULL,'tipuri-de-invelitori','Tabla Faltuita (Seam Roof)','Suprafata plata, continua, fara suruburi vizibile. Imbinarile se fac prin faltare (indoire), ceea ce ii confera un aspect extrem de curat, modern si elegant. Disponibila in culori mate premium.','Buna ziua! Sunt interesat de tabla faltuita pentru acoperis. Puteti sa imi dati un pret?','img/tabla-faltuita.jpg','Tabla faltuita acoperis','icon-452e30cf','Tabla faltuita','Premium','premium',NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-09-25 14:52:39'),(3,1,'acoperis','material',NULL,'tipuri-de-invelitori','Tigla Metalica Profilata','Imita perfect aspectul tiglei ceramice traditionale cu profil 3D, dar este realizata din tabla de otel galvanizat cu strat de vopsea poliester sau acril. Disponibila in maro, rosu, verde, antracit, caramiziu.','Buna ziua! Sunt interesat de tigla metalica profilata. Puteti sa imi dati un pret?','img/tigla-metalica.jpg','Tigla metalica acoperis','icon-3612b68d','Tigla metalica',NULL,NULL,NULL,NULL,1,3,1,'2026-08-27 14:23:46','2026-09-25 14:52:39'),(4,1,'acoperis','material',NULL,'tipuri-de-invelitori','Tabla Zincata Simpla','Suprafata plata, neteda, luciu metalic argintiu-mat specific zincarii la cald. Se poate vopsi ulterior in orice culoare RAL. Aspect sobru, industrial sau traditional.','Buna ziua! Sunt interesat de tabla zincata simpla. Puteti sa imi dati un pret?','img/tabla-zincata.jpg','Tabla zincata simpla','icon-b1c9ac6c','Tabla zincata',NULL,NULL,NULL,NULL,1,4,1,'2026-08-27 14:23:46','2026-09-25 14:52:39'),(5,1,'acoperis','material',NULL,'tigla-si-invelitori-clasice','Tigla Ceramica Naturala','Format clasic sau S, culori: natural argilos, rosu-caramiziu, angoba maro/negru. ~14 buc/m².',NULL,NULL,NULL,'icon-3dffc7d5','Tigla ceramica',NULL,NULL,NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(6,1,'acoperis','material',NULL,'tigla-si-invelitori-clasice','Tigla din Beton Profilata','Profil ondulat sau plat, culori: antracit, brun, rosu-caramiziu, gri. ~10 buc/m².',NULL,NULL,NULL,'icon-3dffc7d5','Tigla beton',NULL,NULL,NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(7,1,'acoperis','material',NULL,'tigla-si-invelitori-clasice','Sindrila Bituminoasa Hexagonala','Armatura fibra sticla, strat bitum modificat SBS, granule minerale. 3m² per pachet.',NULL,NULL,NULL,'icon-3dffc7d5','Sindrila bitum',NULL,NULL,NULL,NULL,1,3,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(8,1,'acoperis','material',NULL,'tigla-si-invelitori-clasice','Tigla Metalica cu Roca Vulcanica','Tabla galvanizata + strat acril + granule bazalt. Culori: negru mat, maro, antracit, verde.',NULL,NULL,NULL,'icon-3dffc7d5','Tigla cu roca',NULL,NULL,NULL,NULL,1,4,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(11,1,'acoperis','material',NULL,'accesorii-acoperis-jgheaburi-folii-coame','Folie Difuzie Acoperis 1.5x50m 115g/mp','3 straturi, permeabilitate la vapori Sd',NULL,NULL,NULL,'icon-3dffc7d5','Folie difuzie',NULL,NULL,NULL,NULL,1,3,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(12,1,'acoperis','material',NULL,'accesorii-acoperis-jgheaburi-folii-coame','Coama Ventilata Acoperis 5m','Coama din plastic rigid cu ventilatie, adaptor universal pentru orice tip de invelitoare. 5m rola.',NULL,NULL,NULL,'icon-3dffc7d5','Coama ventilata',NULL,NULL,NULL,NULL,1,4,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(13,1,'acoperis','material',NULL,'accesorii-acoperis-jgheaburi-folii-coame','Fereastra Mansarda 55x78cm','Rama PVC/lemn, geam termopan 24mm, deschidere pivotanta central. U=1.1 W/m²K.',NULL,NULL,NULL,'icon-3dffc7d5','Fereastra mansarda',NULL,NULL,NULL,NULL,1,5,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(14,1,'acoperis','material',NULL,'accesorii-acoperis-jgheaburi-folii-coame','Fereastra Mansarda 78x118cm cu Rulou','Varianta mare cu rulou blackout integrat. Rama PVC alb, geam 4-16-4mm low-e.',NULL,NULL,NULL,'icon-3dffc7d5','Fereastra mansarda mare',NULL,NULL,NULL,NULL,1,6,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(15,1,'acoperis','material',NULL,'materiale-sarpanta-si-cofraje','Sipca Rindeluita Rasinoase 4x5cm 4m','Rasinoase (brad/molid), uscat in cuptor',NULL,NULL,NULL,'icon-3dffc7d5','Sipca rindeluita',NULL,NULL,NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(16,1,'acoperis','material',NULL,'materiale-sarpanta-si-cofraje','Contrasipca Rindeluita 2.5x5cm 4m','Rasinoase, uscat in cuptor, sectiune 2.5x5cm, lungime 4m. Impregnata antifungic.',NULL,NULL,NULL,'icon-3dffc7d5','Contrasipca',NULL,NULL,NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(17,1,'acoperis','material',NULL,'materiale-sarpanta-si-cofraje','OSB 3 22mm 125x250cm Structural','Clasa umiditate OSB3, grosime 22mm, format 125x250cm. Margini drepte sau faltuite.',NULL,NULL,NULL,'icon-3dffc7d5','OSB 3 22mm',NULL,NULL,NULL,NULL,1,3,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(18,1,'acoperis','material',NULL,'produse-disponibile-in-magazin','Tabla zincata cutata T18 — 0.5mm','Tabla acoperis cutata, zincare la cald, grosime 0.5mm. Disponibila in diverse lungimi si culori.',NULL,NULL,NULL,'icon-3dffc7d5','Tabla zincata cutata',NULL,NULL,NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(19,1,'acoperis','material',NULL,'produse-disponibile-in-magazin','Tigla metalica tip T18 antracit mat 0.5mm','Tabla profilata pentru acoperis, culoare antracit RAL 7016, mat. Latime utila 1.15m.',NULL,NULL,NULL,'icon-3dffc7d5','Tigla metalica tip T',NULL,NULL,NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(20,1,'acoperis','material',NULL,'produse-disponibile-in-magazin','Jgheab PVC semirotund 125mm maro 3m','Jgheab plastic pentru sisteme de scurgere. Diametru 125mm, lungime 3m, culoare maro.',NULL,NULL,NULL,'icon-3dffc7d5','Jgheab PVC semirotun',NULL,NULL,NULL,NULL,1,3,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(21,1,'acoperis','material',NULL,'produse-disponibile-in-magazin','OSB 3 18mm 125x250cm','Placa OSB structural pentru sarpante, podele si cofraje. 18mm, clasa umiditate OSB3.',NULL,NULL,NULL,'icon-3dffc7d5','OSB 3 18mm 125x250cm',NULL,NULL,NULL,NULL,1,4,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(22,1,'acoperis','material',NULL,'produse-disponibile-in-magazin','Folie anticondens acoperis 1.5x50m 75mp','Folie difuzie 3 straturi pentru protectia termoizolatiei. 90g/mp. Lat. 1.5m, lung. 50m.',NULL,NULL,NULL,'icon-3dffc7d5','Folie anticondens ac',NULL,NULL,NULL,NULL,1,5,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(23,2,'izolatie','material',NULL,'placi-termoizolante','Polistiren EPS Grafitat','Placi rigide de culoare gri-argintiu (grafit) sau alb, cu suprafata neteda. Grosimi de la 3cm pana la 20cm. Usoare si usor de taiat cu cutiterul.','Buna ziua! Sunt interesat de polistiren EPS grafitat. Puteti sa imi dati un pret si disponibilitate?','img/polistiren-eps.jpg','Polistiren EPS grafitat','icon-92ca7676','Polistiren EPS','Cel mai vandut','popular',NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-09-25 14:52:40'),(24,2,'izolatie','material',NULL,'placi-termoizolante','Polistiren XPS Extrudat','Placi rigide de culoare galben, albastru sau roz (in functie de producator), cu suprafata neteda sau striata. Mai dens si mai dur decat EPS.','Buna ziua! Sunt interesat de polistiren XPS extrudat. Puteti sa imi dati un pret?','img/polistiren-xps.jpg','Polistiren XPS extrudat','icon-293c7aab','Polistiren XPS','Rezistent umezeala','premium',NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-09-25 14:52:40'),(25,2,'izolatie','material',NULL,'vata-minerala','Vata Minerala Bazaltica (din piatra)','Placi sau rulouri de culoare galben-brun, cu fibra densa si rigida. Se prezinta in placi semidure (fatada) sau rigide (sape). Grosimi 3–20cm.','Buna ziua! Sunt interesat de vata minerala bazaltica. Puteti sa imi dati un pret?','img/vata-bazaltica.jpg','Vata minerala bazaltica','icon-49f67640','Vata bazaltica','Clasa A1 foc','premium',NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-09-25 14:52:40'),(26,2,'izolatie','material',NULL,'vata-minerala','Vata din Fibra de Sticla','Rulouri sau placi moi, de culoare galben deschis, foarte usor de manevrat. Se comprima pentru transport si revine la forma initiala. Fibra mai fina decat vata bazaltica.','Buna ziua! Sunt interesat de vata din fibra de sticla. Puteti sa imi dati un pret?','img/vata-sticla.jpg','Vata minerala fibra de sticla','icon-3ba83274','Vata fibra sticla',NULL,NULL,NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-09-25 14:52:40'),(27,2,'izolatie','material',NULL,'spume-poliuretanice-si-etansare','Spuma Poliuretanica Monocomponent 750ml','Spuma PU monocomponent, expansiune 40L, temperatura aplicare -5°/+40°C. Can 750ml.',NULL,NULL,NULL,'icon-dac1b47b','Spuma PU 750ml',NULL,NULL,NULL,NULL,1,1,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(28,2,'izolatie','material',NULL,'spume-poliuretanice-si-etansare','Silicon Neutru Universal Transparent 280ml','Silicon acetic-free, transparent, temperatura -40°/+150°C, cartus 280ml.',NULL,NULL,NULL,'icon-dac1b47b','Silicon neutru 280ml',NULL,NULL,NULL,NULL,1,2,1,'2026-08-27 14:23:46','2026-08-27 14:23:46'),(29,2,'izolatie','material',NULL,'spume-poliuretanice-si-etansare','Banda Compribanda Etansare 15/4-9mm Rola 5m','Spuma impregnata poliuretan,